#!/usr/bin/env bash
set -Eeuo pipefail
[[ $# -eq 0 ]] || exit 64
t=$(mktemp -d);trap 'rm -rf "$t"' EXIT
git -C "$t" init -q; git -C "$t" remote add origin https://github.com/DaisyCloverSoftware/rum.git; git -C "$t" fetch -q --depth=1 origin 061beefd23bd71cf5902ff2a7724ff78acb515f6; git -C "$t" checkout -q --detach FETCH_HEAD
cd "$t/apps/rate-anything"; npm ci --ignore-scripts --no-audit --no-fund >"$t/npm.log" 2>&1; npx playwright install chromium >"$t/install.log" 2>&1
node --input-type=module <<'JS'
import {chromium,expect} from '@playwright/test';import assert from 'node:assert/strict';
const host='https://dev-rum-ra.daisycloversoftware.uk',p='01m0mw9hkbynssr7kbc0gk534j',main='01m7x6ez57zpsgbv486y9t0y9h',second='01m81mbmqvwr3d1nvfp9gkp3xf';
const browser=await chromium.launch({args:['--no-sandbox','--disable-dev-shm-usage']});const page=await browser.newPage({viewport:{width:1440,height:940}});try{await page.route('**/*',r=>['GET','HEAD','OPTIONS'].includes(r.request().method())&&[host,'https://dev-rum.daisycloversoftware.uk'].includes(new URL(r.request().url()).origin)?r.continue():r.abort());page.on('response',r=>{if(r.status()>=400)console.log('HTTP',r.status(),new URL(r.url()).pathname)});const url=host+'/search?q=Colin%20Furze&active='+p;
for(const [name,id] of [[/^(colinfurze|Colin Furze)$/i,main],[/^2 Much ColinFurze$/i,second]]){await page.goto(url);const cat=page.locator('.rat-category').filter({has:page.getByRole('heading',{name:'Channels',exact:true})});await expect(cat.locator('.rat-linked-card')).toHaveCount(2,{timeout:30000});await cat.locator('.rat-linked-card').filter({has:page.locator('strong').filter({hasText:name})}).click();await expect(page.locator('.rat-active-card__type')).toHaveText('YouTube Channel',{timeout:30000});assert.equal(new URL(page.url()).searchParams.get('active'),id);console.log('SEARCH_LINK_PASS '+id);}
await page.goto(host+'/e/thing~'+p);const panel=page.locator('#connections');await expect(panel.locator('header span')).toHaveText('2 public',{timeout:30000});const group=panel.locator('.rat-workspace-connection-group').filter({has:page.locator('.rat-workspace-connection-group__head strong',{hasText:/^Channels$/})});await expect(group.locator('.rat-workspace-connection')).toHaveCount(2);await group.getByRole('button',{name:/2 Much ColinFurze/i}).click();await expect(page.locator('.rat-workspace-id')).toHaveText(second,{timeout:30000});await page.reload();await expect(page.locator('.rat-workspace-id')).toHaveText(second,{timeout:30000});await panel.getByRole('button',{name:/Colin Furze/i}).click();await expect(page.locator('.rat-workspace-id')).toHaveText(p,{timeout:30000});await page.reload();await expect(panel.locator('header span')).toHaveText('2 public',{timeout:30000});console.log('CHROMIUM_PASS '+JSON.stringify({person:p,main,second,searchChannels:2,detailPublicConnections:2,reciprocal:true,refresh:true,version:browser.version()}));}catch(e){console.log('PAGE_DIAGNOSTIC', (await page.locator('body').innerText()).slice(0,1500));throw e}finally{await browser.close()}
JS
